-- v49（PR#27 之前）完整建库脚本，由 49.json 原样生成，供真实升级测试造老库。
-- v49 identityHash = 934c718aff58c8c860c2491a864d099a
CREATE TABLE IF NOT EXISTS `tools` (`distroId` TEXT NOT NULL, `id` TEXT NOT NULL, `name` TEXT NOT NULL, `description` TEXT NOT NULL, `dependencies` TEXT NOT NULL, `launchType` TEXT NOT NULL, `state` TEXT NOT NULL, `manifestVersion` TEXT NOT NULL, `installedVersion` TEXT, `publisher` TEXT NOT NULL, `category` TEXT NOT NULL, `permissions` TEXT NOT NULL, `homepage` TEXT, `updateStrategy` TEXT NOT NULL, `latestVersion` TEXT, PRIMARY KEY(`distroId`, `id`));
CREATE TABLE IF NOT EXISTS `install_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `distroId` TEXT NOT NULL, `toolId` TEXT NOT NULL, `event` TEXT NOT NULL, `message` TEXT NOT NULL, `createdAt` INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS `install_tasks` (`distroId` TEXT NOT NULL, `toolId` TEXT NOT NULL, `operation` TEXT NOT NULL, `state` TEXT NOT NULL, `message` TEXT NOT NULL, `startedAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`distroId`, `toolId`));
CREATE TABLE IF NOT EXISTS `shared_runtimes` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `version` TEXT, `executablePath` TEXT NOT NULL, `state` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `runtime_dependency_ref` (`toolId` TEXT NOT NULL, `runtimeId` TEXT NOT NULL, PRIMARY KEY(`toolId`, `runtimeId`));
CREATE TABLE IF NOT EXISTS `harness_sessions` (`id` TEXT NOT NULL, `title` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `modelId` TEXT, `modelVariant` TEXT, `workspace` TEXT NOT NULL, `projectType` TEXT NOT NULL, `approvalMode` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_harness_sessions_updatedAt` ON `harness_sessions` (`updatedAt`);
CREATE TABLE IF NOT EXISTS `harness_models` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `provider` TEXT NOT NULL, `model` TEXT NOT NULL, `baseUrl` TEXT NOT NULL, `secretRef` TEXT NOT NULL, `isActive` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `temperature` REAL, `maxTokens` INTEGER, `topP` REAL, `reasoningMode` TEXT, `reasoningEffort` TEXT, `toolCallMode` TEXT, `contextTokens` INTEGER, `inputTokenLimit` INTEGER, `customHeaders` TEXT NOT NULL, `pureChatMode` INTEGER NOT NULL, `visionEnabled` INTEGER NOT NULL, `imageGenerationEnabled` INTEGER NOT NULL, `responseApiEnabled` INTEGER NOT NULL, `apiKeyCount` INTEGER NOT NULL, `requestsPerMinutePerKey` INTEGER NOT NULL, `compactionKeepRecentTokens` INTEGER, `compactionReserveTokens` INTEGER, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `workspaces` (`name` TEXT NOT NULL, `path` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `ownsDirectory` INTEGER NOT NULL, PRIMARY KEY(`name`));
CREATE TABLE IF NOT EXISTS `terminal_sessions` (`id` TEXT NOT NULL, `label` TEXT NOT NULL, `workingDirectory` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `sortOrder` INTEGER NOT NULL, `distributionId` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_terminal_sessions_sortOrder` ON `terminal_sessions` (`sortOrder`);
CREATE TABLE IF NOT EXISTS `agent_memories` (`id` TEXT NOT NULL, `scope` TEXT NOT NULL, `ownerId` TEXT NOT NULL DEFAULT '', `kind` TEXT NOT NULL, `key` TEXT NOT NULL, `value` TEXT NOT NULL, `subjectKey` TEXT NOT NULL DEFAULT '', `revision` INTEGER NOT NULL DEFAULT 1, `pinned` INTEGER NOT NULL DEFAULT 0, `expiresAt` INTEGER DEFAULT null, `lastVerifiedAt` INTEGER NOT NULL DEFAULT 0, `volatility` TEXT NOT NULL DEFAULT 'reference', `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_agent_memories_scope_ownerId_key` ON `agent_memories` (`scope`, `ownerId`, `key`);
CREATE INDEX IF NOT EXISTS `index_agent_memories_scope_ownerId_subjectKey` ON `agent_memories` (`scope`, `ownerId`, `subjectKey`);
CREATE INDEX IF NOT EXISTS `index_agent_memories_pinned` ON `agent_memories` (`pinned`);
CREATE INDEX IF NOT EXISTS `index_agent_memories_expiresAt` ON `agent_memories` (`expiresAt`);
CREATE TABLE IF NOT EXISTS `agent_plans` (`sessionId` TEXT NOT NULL, `goal` TEXT NOT NULL, `stepsJson` TEXT NOT NULL, `status` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`sessionId`));
CREATE TABLE IF NOT EXISTS `agent_scratchpads` (`sessionId` TEXT NOT NULL, `key` TEXT NOT NULL, `value` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`sessionId`, `key`));
CREATE TABLE IF NOT EXISTS `agent_subagents` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `description` TEXT NOT NULL, `systemPrompt` TEXT NOT NULL, `defaultModelId` TEXT DEFAULT null, `defaultModelVariant` TEXT DEFAULT null, `departmentId` TEXT NOT NULL DEFAULT 'custom', `isEnabled` INTEGER NOT NULL, `isBuiltin` INTEGER NOT NULL, `sortOrder` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `agent_subagent_settings` (`id` INTEGER NOT NULL, `autoDelegationEnabled` INTEGER NOT NULL, `catalogRevision` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `mcp_servers` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `description` TEXT NOT NULL, `transportType` TEXT NOT NULL, `command` TEXT NOT NULL, `argsCiphertext` TEXT NOT NULL, `envCiphertext` TEXT NOT NULL, `serverUrl` TEXT NOT NULL, `isEnabled` INTEGER NOT NULL, `isBuiltin` INTEGER NOT NULL, `userToggled` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `agent_skills` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `description` TEXT NOT NULL, `systemPrompt` TEXT NOT NULL, `triggerCommand` TEXT, `iconName` TEXT NOT NULL, `isEnabled` INTEGER NOT NULL, `isBuiltin` INTEGER NOT NULL, `isImmutable` INTEGER NOT NULL, `category` TEXT NOT NULL, `resourcePath` TEXT, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `storage_mount_bindings` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `hostPath` TEXT NOT NULL, `guestPath` TEXT NOT NULL, `enabled` INTEGER NOT NULL, `isSystemDefault` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `tool_settings` (`distroId` TEXT NOT NULL, `toolId` TEXT NOT NULL, `autoStart` INTEGER NOT NULL, PRIMARY KEY(`distroId`, `toolId`));
CREATE TABLE IF NOT EXISTS `agent_approval_requests` (`id` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `toolCallId` TEXT NOT NULL, `toolName` TEXT NOT NULL, `argumentsJson` TEXT NOT NULL, `workspace` TEXT NOT NULL, `riskLevel` TEXT NOT NULL, `reason` TEXT NOT NULL, `summary` TEXT NOT NULL, `status` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `resolvedAt` INTEGER, `operationId` TEXT, `argsHash` TEXT NOT NULL, `expiresAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `agent_approval_settings` (`id` INTEGER NOT NULL, `mode` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `quick_phrases` (`id` TEXT NOT NULL, `title` TEXT NOT NULL, `content` TEXT NOT NULL, `description` TEXT NOT NULL, `iconName` TEXT NOT NULL, `targetProjectType` TEXT, `isEnabled` INTEGER NOT NULL, `sortOrder` INTEGER NOT NULL, `isBuiltin` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `harness_entries` (`sequence` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `id` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `parentId` TEXT, `createdAt` INTEGER NOT NULL, `entryType` TEXT NOT NULL, `customType` TEXT, `payloadJson` TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `index_harness_entries_id` ON `harness_entries` (`id`);
CREATE INDEX IF NOT EXISTS `index_harness_entries_sessionId_sequence` ON `harness_entries` (`sessionId`, `sequence`);
CREATE INDEX IF NOT EXISTS `index_harness_entries_sessionId_parentId` ON `harness_entries` (`sessionId`, `parentId`);
CREATE TABLE IF NOT EXISTS `harness_lanes` (`sessionId` TEXT NOT NULL, `name` TEXT NOT NULL, `leafId` TEXT, `currentOperationId` TEXT, `modelId` TEXT, `thinkingLevel` TEXT NOT NULL, `faulted` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`sessionId`, `name`));
CREATE INDEX IF NOT EXISTS `index_harness_lanes_sessionId_currentOperationId` ON `harness_lanes` (`sessionId`, `currentOperationId`);
CREATE TABLE IF NOT EXISTS `harness_operations` (`id` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `laneName` TEXT NOT NULL, `kind` TEXT NOT NULL, `status` TEXT NOT NULL, `phase` TEXT NOT NULL, `startedAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `startLeafId` TEXT, `stateJson` TEXT NOT NULL, `pendingEffectKind` TEXT, `pendingEffectId` TEXT, `replayPolicy` TEXT, `attempt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_harness_operations_sessionId_laneName` ON `harness_operations` (`sessionId`, `laneName`);
CREATE INDEX IF NOT EXISTS `index_harness_operations_status_updatedAt` ON `harness_operations` (`status`, `updatedAt`);
CREATE TABLE IF NOT EXISTS `harness_queue_items` (`id` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `laneName` TEXT NOT NULL, `operationId` TEXT, `queueType` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `payloadJson` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_harness_queue_items_sessionId_laneName_queueType_createdAt` ON `harness_queue_items` (`sessionId`, `laneName`, `queueType`, `createdAt`);
CREATE INDEX IF NOT EXISTS `index_harness_queue_items_operationId` ON `harness_queue_items` (`operationId`);
CREATE TABLE IF NOT EXISTS `harness_usage` (`sequence` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `id` TEXT NOT NULL, `sessionId` TEXT NOT NULL, `operationId` TEXT, `entryId` TEXT, `provider` TEXT, `modelId` TEXT, `inputTokens` INTEGER NOT NULL, `outputTokens` INTEGER NOT NULL, `reasoningTokens` INTEGER NOT NULL, `cacheReadTokens` INTEGER NOT NULL, `cacheWriteTokens` INTEGER NOT NULL, `estimatedCostUsd` REAL, `adjustment` INTEGER NOT NULL, `detailsJson` TEXT, `createdAt` INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `index_harness_usage_id` ON `harness_usage` (`id`);
CREATE INDEX IF NOT EXISTS `index_harness_usage_sessionId_sequence` ON `harness_usage` (`sessionId`, `sequence`);
CREATE INDEX IF NOT EXISTS `index_harness_usage_operationId` ON `harness_usage` (`operationId`);
CREATE INDEX IF NOT EXISTS `index_harness_usage_entryId` ON `harness_usage` (`entryId`);
CREATE TABLE IF NOT EXISTS `harness_lane_results` (`sessionId` TEXT NOT NULL, `laneName` TEXT NOT NULL, `operationId` TEXT NOT NULL, `outcome` TEXT NOT NULL, `finalEntryId` TEXT, `detailsJson` TEXT, `completedAt` INTEGER NOT NULL, PRIMARY KEY(`sessionId`, `laneName`));
CREATE TABLE IF NOT EXISTS `android_apps` (`packageName` TEXT NOT NULL, `label` TEXT NOT NULL, `uid` INTEGER NOT NULL, `apkPath` TEXT NOT NULL, `isSystemApp` INTEGER NOT NULL, `isEnabled` INTEGER NOT NULL, `isSuspended` INTEGER NOT NULL, `isNetworkRestricted` INTEGER NOT NULL, `lastSyncedAt` INTEGER NOT NULL, PRIMARY KEY(`packageName`));
CREATE TABLE IF NOT EXISTS `build_scripts` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `description` TEXT NOT NULL, `projectType` TEXT NOT NULL, `content` TEXT NOT NULL, `isBuiltin` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `project_build_script_bindings` (`projectName` TEXT NOT NULL, `scriptId` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`projectName`));
CREATE INDEX IF NOT EXISTS `index_project_build_script_bindings_scriptId` ON `project_build_script_bindings` (`scriptId`);
CREATE TABLE IF NOT EXISTS `agent_tasks` (`id` TEXT NOT NULL, `sessionId` TEXT NOT NULL DEFAULT '', `title` TEXT NOT NULL, `description` TEXT NOT NULL, `status` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `errorMessage` TEXT, `progress` REAL NOT NULL, `operationId` TEXT, `startedAt` INTEGER, `completedAt` INTEGER, `nextRunAt` INTEGER, `attemptCount` INTEGER NOT NULL DEFAULT 0, `maxAttempts` INTEGER NOT NULL DEFAULT 2, `autoResume` INTEGER NOT NULL DEFAULT 1, `lastRound` INTEGER NOT NULL DEFAULT 0, `maxRounds` INTEGER NOT NULL DEFAULT 0, `statusDetail` TEXT, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_agent_tasks_status` ON `agent_tasks` (`status`);
CREATE INDEX IF NOT EXISTS `index_agent_tasks_updatedAt` ON `agent_tasks` (`updatedAt`);
CREATE INDEX IF NOT EXISTS `index_agent_tasks_sessionId` ON `agent_tasks` (`sessionId`);
CREATE INDEX IF NOT EXISTS `index_agent_tasks_nextRunAt` ON `agent_tasks` (`nextRunAt`);
CREATE TABLE IF NOT EXISTS `workflows` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `description` TEXT NOT NULL, `category` TEXT NOT NULL, `isBuiltin` INTEGER NOT NULL, `slashCommand` TEXT, `jsonContent` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE INDEX IF NOT EXISTS `index_workflows_slashCommand` ON `workflows` (`slashCommand`);
CREATE TABLE IF NOT EXISTS `workflow_execution_logs` (`executionId` TEXT NOT NULL, `workflowId` TEXT NOT NULL, `startTime` INTEGER NOT NULL, `endTime` INTEGER, `status` TEXT NOT NULL, `finalContextJson` TEXT NOT NULL, PRIMARY KEY(`executionId`), FOREIGN KEY(`workflowId`) REFERENCES `workflows`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_workflow_execution_logs_workflowId` ON `workflow_execution_logs` (`workflowId`);
CREATE INDEX IF NOT EXISTS `index_workflow_execution_logs_startTime` ON `workflow_execution_logs` (`startTime`);
